const $=id=>document.getElementById(id);
const finite=x=>window.FIECore?.Numeric?.finiteOrNull?.(x)??((x===null||x===undefined||(typeof x==='string'&&x.trim()===''))?null:(Number.isFinite(Number(x))?Number(x):null));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(x,d=1)=>{const n=finite(x);return n===null?'—':n.toFixed(d).replace(/\.0$/,'');};
const pct=x=>{const n=finite(x);return n===null?'—':`${n>0?'+':''}${fmt(n)}%`;};
const signed=(x,d=1,suffix='')=>{const n=finite(x);return n===null?'—':`${n>0?'+':''}${fmt(n,d)}${suffix}`;};
const bound=(x,a=0,b=100)=>Math.max(a,Math.min(b,Number(x)||0));
const players=()=>Array.isArray(window.PLAYERS)?window.PLAYERS:[];
const S=()=>window.state||{};
const ctx=()=>window.FIELeagueContext?.current?.()||null;
const format=()=>String(ctx()?.format||window.activeFormatKey?.()||'REDRAFT');
const profile=()=>window.formatProfile?.()||{dynasty:format().includes('DYNASTY'),bestBall:format().includes('BESTBALL'),chopped:format()==='CHOPPED'};
const pid=p=>String(p?.sleeperId||p?.player_id||p?.name||'');
const pos=p=>window.FIECore?.PositionRegistry?.canonical?.(p?.position)||String(p?.position||'').toUpperCase();
const seasonProj=p=>finite(p?.engineSeasonProjection)??finite(p?.sleeperSeasonProjection);
const weekProj=p=>finite(window.FIEProjectionResolver?.week?.(p)?.value)??finite(p?.weeklyProjection)??finite(p?.sleeperWeeklyProjection)??(finite(seasonProj(p))!==null?seasonProj(p)/17:null);
const low=p=>finite(window.FIEProjectionResolver?.range?.(p)?.low)??finite(p?.weeklyFloor)??(finite(weekProj(p))!==null?weekProj(p)*.78:null);
const high=p=>finite(window.FIEProjectionResolver?.range?.(p)?.high)??finite(p?.weeklyCeiling)??(finite(weekProj(p))!==null?weekProj(p)*1.22:null);
const vor=p=>finite(p?.projectedVOR)??finite(p?.replacementAdvantage)??0;
const marketADP=p=>{const n=finite(p?.marketADP);return n!==null&&n>0&&n<998?n:null;};
const legal=p=>{try{return !!(window.isLeagueEligible?.(p)??(p?.leagueEligible!==false&&window.FIELeagueContext?.positionAllowed?.(p?.position)));}catch{return p?.leagueEligible!==false;}};
const dynValue=p=>finite(window.dynastyPlayerValue?.(p))??finite(p?.targetScore)??50;
const futureValue=p=>{const v=finite(p?.futureOpportunity),age=finite(p?.ageCurveScore),tal=finite(p?.tfgModelScore)??finite(p?.pffScore);const xs=[v,age,tal].filter(Number.isFinite);return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;};
const currentValue=p=>{const xs=[finite(p?.currentOpportunity),finite(p?.targetScore),finite(p?.leagueFit)].filter(Number.isFinite);return xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;};
const statusText=p=>p?.injuryStatus||p?.sleeperStatus||'Active';
