const roleMomentum=p=>finite(p?.roleMomentum);
const playerCell=p=>`<div class="fie93-player"><b>${esc(p.name)}</b><small>${esc(pos(p))} · ${esc(p.team||'FA')}</small></div>`;
const chip=(text,cls='')=>`<span class="fie93-chip ${cls}">${esc(text)}</span>`;
function removePanelVisibility(){for(const id of PANEL_IDS){$(id)?.classList.remove('active');if(id==='matchupSimPanel')$(id)?.classList.add('hidden');}}
function showMain(){window.FIESurfaceRouter?.cleanupFor?.(S().activeTab);removePanelVisibility();$('mainArea')?.classList.remove('hidden');}
function showPanel(id){window.FIESurfaceRouter?.cleanupFor?.(S().activeTab);removePanelVisibility();$('mainArea')?.classList.add('hidden');$(id)?.classList.remove('hidden');$(id)?.classList.add('active');$('weeklyControls')?.classList.add('hidden');}
function formatLabel(){return window.FIELeagueProfileResolver?.label?.(format())||format().replaceAll('_',' + ');}
function rankMap(rows,valueFn,{ascending=false,group=true}={}){const groups={};for(const p of rows){const g=group?pos(p):'ALL';(groups[g]??=[]).push(p);}const out=new Map();for(const xs of Object.values(groups)){xs.sort((a,b)=>{const av=finite(valueFn(a)),bv=finite(valueFn(b));if(av===null)return 1;if(bv===null)return-1;return ascending?av-bv:bv-av;});xs.forEach((p,i)=>out.set(pid(p),i+1));}return out;}
function marketRanks(rows,group=true){return rankMap(rows,marketADP,{ascending:true,group});}
function boardShape(p){try{return window.FIE_DRAFT_V71?.earlyWeeksFor?.(p)||{mean:weekProj(p),floor:low(p),ceiling:high(p),n:0};}catch{return{mean:weekProj(p),floor:low(p),ceiling:high(p),n:0};}}
function transparentDraftScore(p){return finite(window.FIEDraftBaseValueService?.rowFor?.(p)?.baseValue)??finite(vor(p))??finite(dynValue(p))??0;}
function tierMap(rows,scoreFn){const svc=window.FIEDraftBaseValueService?.rows?.()||[],m=new Map(svc.map(x=>[x.id,x.tier]));if(m.size)return m;const xs=[...rows].filter(p=>finite(scoreFn(p))!==null).sort((a,b)=>scoreFn(b)-scoreFn(a));xs.forEach((p,i)=>m.set(pid(p),Math.floor(i/Math.max(8,(S().rosters?.length||12)*2))+1));return m;}
function rosterPool(rid=S().selectedRoster){return players().filter(p=>legal(p)&&Number(p.ownerRosterId)===Number(rid));}
function decorated(p){return window.FIECore?.RosterValueService?.decorate?.(p,format())||p;}
function exactRosterContribution(p,rid=S().selectedRoster){const pool=rosterPool(rid);if(!pool.length)return null;const rest=pool.filter(x=>pid(x)!==pid(p)),rv=window.FIECore?.LineupOptimizer;if(!rv)return null;const opts={format:format(),rosterPositions:S().league?.roster_positions||[]};const before=rv.rosterUtility(rest.map(decorated),opts),after=rv.rosterUtility(pool.map(decorated),opts);return after.total-before.total;}
function lineup(valueFn=weekProj,pool=rosterPool()){return window.FIECore?.LineupOptimizer?.optimize?.(pool,S().league?.roster_positions||[],valueFn)||{total:0,assignment:[],selectedPlayerIds:[],benchPlayerIds:[]};}
function lineupRoleMap(pool=rosterPool()){const opt=lineup(seasonProj,pool),m=new Map();for(const a of opt.assignment)m.set(String(a.playerId),a.slot);for(const p of pool)if(!m.has(pid(p)))m.set(pid(p),'BENCH');return m;}
function weeklyBenchDelta(p,pool=rosterPool()){const opt=lineup(weekProj,pool);if(!opt.selectedPlayerIds.includes(pid(p)))return 0;const without=lineup(weekProj,pool.filter(x=>pid(x)!==pid(p)));return opt.total-without.total;}
function matchupDelta(p){const a=finite(p?.matchupAdjustment);if(a!==null)return a;const f=finite(p?.matchupFactor);if(f!==null)return(f-1)*100;const score=finite(p?.matchupScore);return score!==null?(score-50)/5:null;}
function replacementDepth(p){const same=players().filter(x=>legal(x)&&x.availability==='FA'&&pos(x)===pos(p));const pv=seasonProj(p);return same.filter(x=>seasonProj(x)>=pv*.8).length;}
function shortTerm(p){const sh=boardShape(p);return sh.mean*.65+sh.floor*.35;}
function filteredBase(tab){let xs=players().filter(legal);if(tab==='offense')xs=xs.filter(p=>p.side==='OFF'||['QB','RB','WR','TE','K','DEF'].includes(pos(p)));if(tab==='idp')xs=xs.filter(p=>p.side==='IDP'||['DL','EDGE','IDL','LB','DB','CB','S'].includes(pos(p)));if(tab==='myroster'||tab==='startsit')xs=xs.filter(p=>Number(p.ownerRosterId)===Number(S().selectedRoster));if(tab==='waivers')xs=xs.filter(p=>p.availability==='FA');if(tab==='targets'){if(!profile().dynasty)return[];xs=xs.filter(p=>Number(p.ownerRosterId)!==Number(S().selectedRoster));}
  const q=$('searchFilter')?.value?.trim().toLowerCase();if(q)xs=xs.filter(p=>[p.name,p.team,p.position,p.owner,p.role,p.roleProfile].join(' ').toLowerCase().includes(q));
  const po=$('posFilter')?.value;if(po&&po!=='ALL')xs=xs.filter(p=>pos(p)===pos({position:po}));
  if(['all','offense','idp'].includes(tab)){const av=$('availFilter')?.value;if(av&&av!=='ALL')xs=xs.filter(p=>p.availability===av||(!S().matched&&av==='UNKNOWN'));const tm=$('teamFilter')?.value;if(tm&&tm!=='ALL')xs=xs.filter(p=>p.team===tm);const ys=[...($('yearFilter')?.selectedOptions||[])].map(o=>o.value).filter(x=>x!=='ALL');if(ys.length)xs=xs.filter(p=>ys.includes(window.experienceBucket?.(p.yearsExp)));}
  return xs;
}
function configureFilters(tab){const filters=$('filters');if(!filters)return;filters.classList.add('fie93-compact');const wrap=id=>$(id)?.closest('div');const show=(id,on)=>wrap(id)?.classList.toggle('fie93-hidden',!on);const playerBrowse=['all','offense','idp'].includes(tab);show('searchFilter',true);show('availFilter',playerBrowse);show('yearFilter',playerBrowse);show('posFilter',true);show('teamFilter',playerBrowse);show('minScore',false);$('exportBtn')?.classList.toggle('fie93-hidden',false);$('rosterPickerWrap')?.classList.toggle('hidden',tab!=='myroster');
  const y=$('yearFilter');if(y){if(![...y.options].some(o=>o.value==='ALL'))y.insertAdjacentHTML('afterbegin','<option value="ALL">All</option>');y.size=1;}
  let extra=$('fie93RosterStateWrap');if(tab==='startsit'){if(!extra){extra=document.createElement('div');extra.id='fie93RosterStateWrap';extra.className='fie93-filter-extra';extra.innerHTML='<span class="filter-label">Lineup view</span><select id="fie93RosterStateFilter"><option value="ALL">All</option><option value="STARTER">Starters</option><option value="BENCH">Bench</option></select>';filters.insertBefore(extra,$('resetBtn'));$('fie93RosterStateFilter').onchange=e=>{UI.weeklyRosterFilter=e.target.value;UI.page.startsit=80;window.render?.();};}extra.classList.remove('fie93-hidden');$('fie93RosterStateFilter').value=UI.weeklyRosterFilter;}else extra?.classList.add('fie93-hidden');
  const wc=$('weeklyControls');wc?.classList.toggle('hidden',tab!=='startsit');if(tab==='startsit'){wrap('riskSelect')?.classList.add('fie93-hidden');wrap('oddsKey')?.classList.add('fie93-hidden');}
  $('waiverRecommendations')?.classList.add('fie93-hidden');$('fieFaabStrategy')?.classList.add('fie93-hidden');
}
function sortRows(rows,schema,tab,defaultKey,defaultDir=-1){const cfg=UI.sort[tab]||{key:defaultKey,dir:defaultDir};const col=schema.find(c=>c.key===cfg.key)||schema.find(c=>c.key===defaultKey)||schema[0];return [...rows].sort((a,b)=>{const av=col.value?col.value(a):a[col.key],bv=col.value?col.value(b):b[col.key];if(av===null||av===undefined)return 1;if(bv===null||bv===undefined)return-1;if(typeof av==='string'||typeof bv==='string')return String(av).localeCompare(String(bv))*cfg.dir;return(Number(av)-Number(bv))*cfg.dir;});}
function renderTable(tab,rows,schema,{defaultKey=schema[0]?.key,defaultDir=-1,note='',rowId=r=>pid(r),empty='No players match the current league and filters.'}={}){showMain();configureFilters(tab);const table=$('mainArea')?.querySelector('.table-card table'),head=table?.querySelector('thead tr'),body=$('tbody');if(!table||!head||!body)return;table.className='fie93-table';table.closest('.table-card')?.classList.add('fie93-table-card');head.innerHTML=schema.map(c=>`<th data-fie93-sort="${esc(c.key)}">${esc(c.label)}${c.estimate?' *':''}</th>`).join('');const sorted=sortRows(rows,schema,tab,defaultKey,defaultDir),limit=UI.page[tab]||80,shown=sorted.slice(0,limit);body.innerHTML=shown.length?shown.map(r=>`<tr data-fie93-id="${esc(rowId(r))}">${schema.map(c=>`<td class="${c.className||''}">${c.render?c.render(r):esc(c.value?c.value(r):r[c.key])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${schema.length}"><div class="empty">${esc(empty)}</div></td></tr>`;
  $('resultText').innerHTML=`${sorted.length} result${sorted.length===1?'':'s'}${note?` · <span class="fie93-context-note">${note}</span>`:''}`;const cfg=UI.sort[tab]||{key:defaultKey,dir:defaultDir},lab=schema.find(c=>c.key===cfg.key)?.label||defaultKey;$('sortBadge').textContent=`Sorted: ${lab} ${cfg.dir<0?'↓':'↑'}`;
  const tools=$('resultText')?.parentElement;let more=$('fie93ShowMore');if(sorted.length>limit){if(!more){more=document.createElement('button');more.id='fie93ShowMore';more.className='btn ghost';more.style.padding='5px 8px';tools?.appendChild(more);}more.classList.remove('fie93-hidden');more.textContent=`Show ${Math.min(80,sorted.length-limit)} more`;more.onclick=()=>{UI.page[tab]=limit+80;renderActiveTab();};}else more?.classList.add('fie93-hidden');
  head.querySelectorAll('th[data-fie93-sort]').forEach(th=>th.onclick=()=>{const key=th.dataset.fie93Sort,old=UI.sort[tab]||{key:defaultKey,dir:defaultDir};UI.sort[tab]=old.key===key?{key,dir:-old.dir}:{key,dir:(schema.find(c=>c.key===key)?.ascending?1:-1)};UI.page[tab]=80;renderActiveTab();});
  body.querySelectorAll('tr[data-fie93-id]').forEach(tr=>tr.onclick=()=>window.openDrawer?.(tr.dataset.fie93Id));
}
function baseRanks(scoreFn=transparentDraftScore){const xs=players().filter(legal),svc=window.FIEDraftBaseValueService?.rows?.()||[],fiePos=new Map(),fieOverall=new Map();if(svc.length){for(const x of svc){fiePos.set(x.id,x.positionRank);fieOverall.set(x.id,x.overallRank);}}else{for(const [k,v] of rankMap(xs,scoreFn))fiePos.set(k,v);for(const [k,v] of rankMap(xs,scoreFn,{group:false}))fieOverall.set(k,v);}const mktPos=marketRanks(xs,true),mktOverall=marketRanks(xs,false);return{xs,fiePos,fieOverall,mktPos,mktOverall,canonical:new Map(svc.map(x=>[x.id,x]))};}
function renderDraft(){const rows=filteredBase('draft'),r=baseRanks(transparentDraftScore),tiers=tierMap(r.xs,transparentDraftScore),f=format(),p=profile();let schema;
  if(f==='DYNASTY'){schema=[{key:'rank',label:'Draft Rank',value:x=>r.fieOverall.get(pid(x)),render:x=>`<b class="fie93-rank">#${r.fieOverall.get(pid(x))||'—'}</b>`},{key:'player',label:'Player',value:x=>x.name,render:playerCell,className:'fie93-player'},{key:'posrank',label:'FIE Pos',value:x=>r.fiePos.get(pid(x)),render:x=>`#${r.fiePos.get(pid(x))||'—'}`},{key:'market',label:'Market Rank',value:x=>r.mktOverall.get(pid(x)),render:x=>r.mktOverall.get(pid(x))?`#${r.mktOverall.get(pid(x))}`:'—'},{key:'marketpos',label:'Market Pos',value:x=>r.mktPos.get(pid(x)),render:x=>r.mktPos.get(pid(x))?`#${r.mktPos.get(pid(x))}`:'—'},{key:'gap',label:'Value Gap',value:x=>(r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0),render:x=>edgeCell((r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0))},{key:'current',label:'Current Value',value:currentValue,render:x=>fmt(currentValue(x))},{key:'future',label:'Future Value',estimate:true,value:futureValue,render:x=>`${fmt(futureValue(x))} ${chip('Estimate','estimate')}`},{key:'age',label:'Age',value:x=>finite(x.age),render:x=>x.age??'—'}];}
  else if(p.bestBall){schema=[{key:'rank',label:'Draft Rank',value:x=>r.fieOverall.get(pid(x)),render:x=>`<b class="fie93-rank">#${r.fieOverall.get(pid(x))||'—'}</b>`},{key:'player',label:'Player',value:x=>x.name,render:playerCell},{key:'posrank',label:'FIE Pos',value:x=>r.fiePos.get(pid(x)),render:x=>`#${r.fiePos.get(pid(x))||'—'}`},{key:'adp',label:'ADP',ascending:true,value:marketADP,render:x=>fmt(marketADP(x))},{key:'edge',label:'Market Edge',value:x=>(r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0),render:x=>edgeCell((r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0))},{key:'proj',label:'Season Proj',value:seasonProj,render:x=>fmt(seasonProj(x))},{key:'ceiling',label:'Ceiling / Profile',estimate:true,value:x=>boardShape(x).ceiling,render:x=>`${fmt(boardShape(x).ceiling)} · ${esc(bestBallDraftProfile(x))} ${empiricalRange(x)?'':chip('Estimate','estimate')}`},{key:'vor',label:'VOR',value:vor,render:x=>signed(vor(x))},{key:'tier',label:'Tier',value:x=>tiers.get(pid(x)),render:x=>`T${tiers.get(pid(x))||'—'}`}];}
  else if(p.chopped){schema=[{key:'rank',label:'Draft Rank',value:x=>r.fieOverall.get(pid(x)),render:x=>`<b class="fie93-rank">#${r.fieOverall.get(pid(x))||'—'}</b>`},{key:'player',label:'Player',value:x=>x.name,render:playerCell},{key:'posrank',label:'FIE Pos',value:x=>r.fiePos.get(pid(x)),render:x=>`#${r.fiePos.get(pid(x))||'—'}`},{key:'adp',label:'ADP',ascending:true,value:marketADP,render:x=>fmt(marketADP(x))},{key:'edge',label:'Market Edge',value:x=>(r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0),render:x=>edgeCell((r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0))},{key:'early',label:'W1–4 Proj',value:x=>boardShape(x).mean,render:x=>fmt(boardShape(x).mean)},{key:'down',label:'Downside',value:x=>boardShape(x).floor,render:x=>`${fmt(boardShape(x).floor)} ${empiricalRange(x)?'':chip('Estimate','estimate')}`},{key:'depth',label:'Replacement Depth',estimate:true,value:replacementDepth,render:x=>`${replacementDepth(x)} ${chip('Estimate','estimate')}`},{key:'tier',label:'Tier',value:x=>tiers.get(pid(x)),render:x=>`T${tiers.get(pid(x))||'—'}`}];}
  else{schema=[{key:'rank',label:'Draft Rank',value:x=>r.fieOverall.get(pid(x)),render:x=>`<b class="fie93-rank">#${r.fieOverall.get(pid(x))||'—'}</b>`},{key:'player',label:'Player',value:x=>x.name,render:playerCell},{key:'posrank',label:'FIE Pos',value:x=>r.fiePos.get(pid(x)),render:x=>`#${r.fiePos.get(pid(x))||'—'}`},{key:'adp',label:'Sleeper ADP',ascending:true,value:marketADP,render:x=>fmt(marketADP(x))},{key:'marketpos',label:'Market Pos',value:x=>r.mktPos.get(pid(x)),render:x=>r.mktPos.get(pid(x))?`#${r.mktPos.get(pid(x))}`:'—'},{key:'edge',label:'Market Edge',value:x=>(r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0),render:x=>edgeCell((r.mktPos.get(pid(x))||0)-(r.fiePos.get(pid(x))||0))},{key:'proj',label:'Season Proj',value:seasonProj,render:x=>fmt(seasonProj(x))},{key:'vor',label:'VOR',value:vor,render:x=>signed(vor(x))},{key:'tier',label:'Tier',value:x=>tiers.get(pid(x)),render:x=>`T${tiers.get(pid(x))||'—'}`}];}
  renderTable('draft',rows,schema,{defaultKey:'rank',defaultDir:1,note:`${formatLabel()} · roster-neutral to your owned players, but scarcity uses league scoring, exact starter slots, FLEX/SF eligibility and replacement cutoffs.`});
}
function edgeCell(v){const n=finite(v);if(n===null||n===0)return'<span class="muted">0</span>';return`<b class="fie93-pos-edge ${n>0?'positive':'negative'}">${n>0?'+':''}${fmt(n,0)}</b>`;}
