function bestBallProfile(p,pool){const rank=[...pool].sort((a,b)=>transparentDraftScore(b)-transparentDraftScore(a)).findIndex(x=>pid(x)===pid(p))+1,ceil=high(p),mean=weekProj(p);if(rank&&rank<=Math.max(3,Math.ceil(pool.length*.25)))return'Core';if(ceil>mean*1.28)return'Spike contributor';if(vor(p)>0)return'Depth';return'Redundant';}
function bestBallDraftProfile(p){const rawMean=weekProj(p),ceil=high(p),floor=low(p);if(rawMean===null||ceil===null||floor===null)return'Low-data';const mean=Math.max(.1,rawMean),spike=(ceil-mean)/mean,down=(mean-floor)/mean;if(vor(p)>0&&spike>=.25)return'Anchor + spike';if(spike>=.30)return'Spike';if(vor(p)>0&&down<=.18)return'Volume';if(vor(p)>0)return'Balanced';return'Depth';}
function bestBallPortfolioFit(p){if(!profile().bestBall)return null;const pool=rosterPool(),position=pos(p),all=players().filter(legal),demand=window.FIECore?.LeagueDemandService?.starterDemand?.({league:S().league,players:all,valueFn:seasonProj}),perTeam=finite(demand?.perTeam?.[position])??0,samePos=pool.filter(x=>pos(x)===position).length,targetDepth=Math.max(1,Math.ceil(perTeam)+(position==='QB'||position==='TE'?1:2));let score=50+(targetDepth-samePos)*7;const passCatcher=['WR','TE'].includes(position),hasQB=pool.some(x=>pos(x)==='QB'&&x.team&&x.team===p.team),hasCatcher=pool.some(x=>['WR','TE'].includes(pos(x))&&x.team&&x.team===p.team);if((passCatcher&&hasQB)||(position==='QB'&&hasCatcher))score+=12;const mean=Math.max(.1,weekProj(p)),spike=(high(p)-mean)/mean;if(spike>=.25)score+=8;if(samePos>targetDepth+1)score-=10;score=bound(score);const label=score>=72?'Strong':score>=58?'Positive':score>=42?'Neutral':'Redundant',reasons=[];if(samePos<targetDepth)reasons.push(`${position} construction need`);if((passCatcher&&hasQB)||(position==='QB'&&hasCatcher))reasons.push('stack correlation');if(spike>=.25)reasons.push('ceiling complement');if(samePos>targetDepth+1)reasons.push('positional redundancy');return{score,label,reason:reasons.join(' · ')||'balanced construction'};}
function weeklyDecisionState(){
  const pool=rosterPool(),points=lineup(weekProj,pool),sim=window.FIEDecisionEngines?.leagueSim?.data?.current||null;
  if(UI.weeklyMode!=='win'||!sim?.lineupSearch?.best?.starters?.length)return{pool,points,chosen:points,sim,same:true,winGain:null,sacrifice:0};
  const best=sim.lineupSearch.best,mean=sim.lineupSearch.meanCandidate||best,ids=new Set(best.starters.map(pid));
  const forced=lineup(p=>ids.has(pid(p))?10000+weekProj(p):weekProj(p),pool),chosen={...forced,selectedPlayerIds:[...ids],total:finite(best.mean)??points.total};
  const meanIds=new Set((mean.starters||[]).map(pid)),same=ids.size===meanIds.size&&[...ids].every(id=>meanIds.has(id));
  const winGain=finite(best?.prob?.win)!==null&&finite(mean?.prob?.win)!==null?(best.prob.win-mean.prob.win)*100:null;
  return{pool,points,chosen,sim,same,winGain,sacrifice:Math.max(0,points.total-(finite(best.mean)??points.total))};
}
function weeklyPanel(){
  let el=$('fie93WeeklyPanel');
  if(!el){el=document.createElement('div');el.id='fie93WeeklyPanel';el.className='fie93-lineup-panel';$('mainArea')?.insertBefore(el,$('filters'));}
  const {points,chosen,sim,same,winGain,sacrifice}=weeklyDecisionState(),mode=UI.weeklyMode;
  const opp=sim?fmt(sim.oppMean):'—',win=mode==='win'&&finite(sim?.lineupSearch?.best?.prob?.win)!==null?`${fmt(sim.lineupSearch.best.prob.win*100)}%`:finite(sim?.win)!==null?`${fmt(sim.win*100)}%`:'—';
  el.innerHTML=`<div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><b>Optimal projected starting lineup</b><div class="fie93-context-note">Season ${window.FIECore?.SeasonResolver?.resolve?.()||S().league?.season||'—'} · Week ${window.currentWeek?.()||1} · Exact Sleeper slot eligibility. Win-probability mode is opponent-aware and uses the current modeled matchup distribution.</div></div><div class="fie93-lineup-tabs"><button class="btn ${mode==='points'?'primary':'ghost'}" data-mode="points">Max expected points</button><button class="btn ${mode==='win'?'primary':'ghost'}" data-mode="win">Max win probability</button></div></div><div class="fie93-lineup-grid"><div class="fie93-mini"><span>Your projected total</span><b>${fmt(chosen.total)}</b></div><div class="fie93-mini"><span>Opponent projected total</span><b>${opp}</b></div><div class="fie93-mini"><span>Modeled win probability</span><b>${win}</b></div><div class="fie93-mini"><span>Cost vs max points</span><b>${mode==='win'?signed(-sacrifice,1,' pts'):'0 pts'}</b></div></div>${mode==='win'?`<div class="notice" style="margin-top:8px">${lsText(sim,same,winGain)}</div>`:''}`;
  el.querySelectorAll('[data-mode]').forEach(button=>button.onclick=async()=>{
    UI.weeklyMode=button.dataset.mode;
    if(UI.weeklyMode==='win'&&!window.FIEDecisionEngines?.leagueSim?.data?.current){try{await window.FIEDecisionEngines?.runLeagueSimulation?.(false);}catch{}}
    renderActiveTab();
  });
}
function lsText(sim,same,winGain){if(!sim?.lineupSearch)return'Matchup model is not ready yet. Refresh weekly context or open Matchup & Playoffs once; max-points remains authoritative until opponent simulation is available.';if(same)return'Max-points lineup is also the modeled max-win-probability lineup.';return`Opponent-aware optimization changes the lineup${finite(winGain)!==null?` for an estimated ${signed(winGain,1,' pp')} win-probability change`:''}. This is a simulation estimate, not a prospectively calibrated transaction effect.`;}
