function waiverTransactions(){
  const rid=S().selectedRoster,fas=filteredBase('waivers'),basePool=rosterPool(rid),baseWeek=lineup(weekProj,basePool).total,rows=[];
  const diag={freeAgents:fas.length,considered:0,noSwap:0,nonPositive:0,returned:0};
  for(const p of fas.slice().sort((a,b)=>(finite(b.waiverScore)??0)-(finite(a.waiverScore)??0)).slice(0,120)){
    diag.considered++;const swap=window.bestWaiverSwap?.(p,rid);if(!swap){diag.noSwap++;continue;}
    const next=basePool.filter(x=>pid(x)!==pid(swap.drop)).concat(p),nextWeek=lineup(weekProj,next).total,weekGain=finite(nextWeek)!==null&&finite(baseWeek)!==null?nextWeek-baseWeek:null,next3=finite(p.m5WaiverNext3),drop3=finite(swap.drop?.m5WaiverNext3),wp=weekProj(p),wd=weekProj(swap.drop),next3Gain=next3!==null&&drop3!==null?next3-drop3:(wp!==null&&wd!==null?(wp-wd)*3:null),faab=window.faabRecommendation?.(p,swap,.5),gain=finite(swap.gain);
    if(gain===null){diag.noSwap++;continue;}if(gain<=0&&(weekGain===null||weekGain<=0))diag.nonPositive++;
    rows.push({p,drop:swap.drop,swap,gain,weekGain,next3Gain,next3Estimate:next3===null||drop3===null,faab,action:gain>3||(weekGain!==null&&weekGain>1)?'CLAIM':gain>0?'WATCH':'PASS'});
  }
  rows.sort((a,b)=>b.gain-a.gain);diag.returned=rows.length;window.FIEWaiverDiagnostics=window.FIEWaiverDiagnostics||{};window.FIEWaiverDiagnostics.last=`${diag.freeAgents} FA · ${diag.considered} considered · ${diag.noSwap} rejected/no legal swap · ${diag.nonPositive} non-positive · ${diag.returned} shown`;return rows;
}
