function scoringCategory(key){const k=String(key||'').toLowerCase();if(k.startsWith('pass')||k.includes('pass_'))return'Passing';if(k.startsWith('rush'))return'Rushing';if(k.startsWith('rec')||k.includes('_rec'))return'Receiving';if(/fg|xp|kick/.test(k))return'Kicking';if(/idp|tkl|tackle|qb_hit|pass_def|def_td|solo|assist/.test(k))return'IDP';if(/sack|int|fum|pts_allow|yds_allow|safe|def_/.test(k))return'D/ST';if(k.includes('bonus'))return'Bonus';return'Other';}
